do $$ begin if to_regclass('public.fin_sso_connections') is not null or to_regclass('public.fin_sso_domains') is not null or to_regclass('public.fin_sso_events') is not null or to_regprocedure('public.fin_sso_authorize(uuid,uuid,text,text,timestamp with time zone)') is not null or to_regprocedure('public.fin_sso_password_allowed(text)') is not null or (select value from public.fin_settings where key='schema_version') <> 'financial-public-api-1' then raise exception 'SSO rollback incomplete'; end if; end $$;
